/// A user-created point on the project's continuous timeline. [positionMs] is
/// global milliseconds from the start of the logical recording; [sessionId]
/// identifies the source segment containing that point. Never generated by AI.
class RavenBookmark {
  const RavenBookmark({
    required this.id,
    required this.sessionId,
    required this.positionMs,
    required this.label,
    required this.createdAt,
  });

  final String id;
  final String sessionId;
  final int positionMs;
  final String label;
  final DateTime createdAt;

  Map<String, Object?> toJson() => <String, Object?>{
        'id': id,
        'sessionId': sessionId,
        'positionMs': positionMs,
        'label': label,
        'createdAt': createdAt.toIso8601String(),
      };

  factory RavenBookmark.fromJson(Map<String, Object?> json) => RavenBookmark(
        id: json['id'] as String,
        sessionId: json['sessionId'] as String? ?? '',
        positionMs: (json['positionMs'] as num?)?.toInt() ?? 0,
        label: json['label'] as String? ?? 'Bookmark',
        createdAt: DateTime.tryParse(json['createdAt'] as String? ?? '') ??
            DateTime.fromMillisecondsSinceEpoch(0),
      );
}

class RavenAudioSession {
  const RavenAudioSession({
    required this.id,
    required this.audioPath,
    required this.createdAt,
    required this.durationMs,
    this.format = 'm4a',
    this.name = '',
    this.sampleRate = 44100,
    this.recoverablePcm16 = false,
  });

  final String id;
  final String audioPath;
  final DateTime createdAt;
  final int durationMs;
  final String format;
  final String name;
  final int sampleRate;
  final bool recoverablePcm16;

  RavenAudioSession copyWith({
    String? audioPath,
    DateTime? createdAt,
    int? durationMs,
    String? format,
    String? name,
    int? sampleRate,
    bool? recoverablePcm16,
  }) {
    return RavenAudioSession(
      id: id,
      audioPath: audioPath ?? this.audioPath,
      createdAt: createdAt ?? this.createdAt,
      durationMs: durationMs ?? this.durationMs,
      format: format ?? this.format,
      name: name ?? this.name,
      sampleRate: sampleRate ?? this.sampleRate,
      recoverablePcm16: recoverablePcm16 ?? this.recoverablePcm16,
    );
  }

  Map<String, Object?> toJson() => <String, Object?>{
        'id': id,
        'audioPath': audioPath,
        'createdAt': createdAt.toIso8601String(),
        'durationMs': durationMs,
        'format': format,
        'name': name,
        'sampleRate': sampleRate,
        'recoverablePcm16': recoverablePcm16,
      };

  factory RavenAudioSession.fromJson(Map<String, Object?> json) {
    return RavenAudioSession(
      id: json['id'] as String,
      audioPath: json['audioPath'] as String,
      createdAt: DateTime.parse(json['createdAt'] as String),
      durationMs: (json['durationMs'] as num?)?.toInt() ?? 0,
      format: json['format'] as String? ?? 'm4a',
      name: json['name'] as String? ?? '',
      sampleRate: (json['sampleRate'] as num?)?.toInt() ?? 44100,
      recoverablePcm16: json['recoverablePcm16'] as bool? ?? false,
    );
  }
}

/// The stable RAVEN project record. A project ID never depends on its title or category.
class RavenProject {
  const RavenProject({
    required this.id,
    required this.title,
    required this.createdAt,
    required this.updatedAt,
    required this.sessions,
    this.isStandalone = false,
    this.category = 'Uncategorized',
    this.isFavorite = false,
    this.isTrashed = false,
    this.trashedAt,
    this.isDraft = false,
    this.notes = '',
    this.tags = const <String>[],
    this.bookmarks = const <RavenBookmark>[],
    this.isAudioProtected = false,
    this.audioProtectionSalt,
    this.requiresAppPin = false,
    this.aiGeneratedContent = const <String, String>{},
    this.masterAudioPath,
    this.publicCopyLocation,
    this.publicFolderLocation,
  });

  final String id;
  final String title;
  final DateTime createdAt;
  final DateTime updatedAt;
  final List<RavenAudioSession> sessions;
  final bool isStandalone;
  final String category;
  final bool isFavorite;
  final bool isTrashed;
  final DateTime? trashedAt;
  final bool isDraft;
  final String notes;
  final List<String> tags;
  final List<RavenBookmark> bookmarks;

  /// Metadata flag only. Playback gating must be enforced by the security service.
  final bool isAudioProtected;

  /// Random PBKDF2 salt for password-protected audio; never contains a password.
  final String? audioProtectionSalt;

  /// Requires the configured RAVEN app PIN before opening this project.
  final bool requiresAppPin;

  /// AI outputs are stored separately from original notes/transcripts.
  final Map<String, String> aiGeneratedContent;

  /// Optional, automatically generated continuous master file. Session files remain as recovery sources.
  final String? masterAudioPath;

  /// URI or path for RAVEN-managed user-visible copy, separate from the private original.
  final String? publicCopyLocation;

  /// URI or path of the public copy of the whole project folder (audio, notes,
  /// attachments). Null while the project folder is private.
  final String? publicFolderLocation;

  /// True when the project folder is visible in the device's public RAVEN folder.
  bool get isPublic =>
      publicFolderLocation != null || publicCopyLocation != null;

  String? get latestAudioPath =>
      masterAudioPath ?? (sessions.isEmpty ? null : sessions.last.audioPath);

  int get durationMs =>
      sessions.fold<int>(0, (sum, session) => sum + session.durationMs);

  RavenProject copyWith({
    String? title,
    DateTime? updatedAt,
    List<RavenAudioSession>? sessions,
    bool? isStandalone,
    String? category,
    bool? isFavorite,
    bool? isTrashed,
    DateTime? trashedAt,
    bool clearTrashedAt = false,
    bool? isDraft,
    String? notes,
    List<String>? tags,
    List<RavenBookmark>? bookmarks,
    bool? isAudioProtected,
    String? audioProtectionSalt,
    bool clearAudioProtectionSalt = false,
    bool? requiresAppPin,
    Map<String, String>? aiGeneratedContent,
    String? masterAudioPath,
    bool clearMasterAudioPath = false,
    String? publicCopyLocation,
    bool clearPublicCopyLocation = false,
    String? publicFolderLocation,
    bool clearPublicFolderLocation = false,
  }) {
    return RavenProject(
      id: id,
      title: title ?? this.title,
      createdAt: createdAt,
      updatedAt: updatedAt ?? DateTime.now(),
      sessions: sessions ?? this.sessions,
      isStandalone: isStandalone ?? this.isStandalone,
      category: category ?? this.category,
      isFavorite: isFavorite ?? this.isFavorite,
      isTrashed: isTrashed ?? this.isTrashed,
      trashedAt: clearTrashedAt || isTrashed == false
          ? null
          : (trashedAt ?? this.trashedAt),
      isDraft: isDraft ?? this.isDraft,
      notes: notes ?? this.notes,
      tags: tags ?? this.tags,
      bookmarks: bookmarks ?? this.bookmarks,
      isAudioProtected: isAudioProtected ?? this.isAudioProtected,
      audioProtectionSalt: clearAudioProtectionSalt
          ? null
          : (audioProtectionSalt ?? this.audioProtectionSalt),
      requiresAppPin: requiresAppPin ?? this.requiresAppPin,
      aiGeneratedContent: aiGeneratedContent ?? this.aiGeneratedContent,
      masterAudioPath: clearMasterAudioPath
          ? null
          : (masterAudioPath ?? this.masterAudioPath),
      publicCopyLocation: clearPublicCopyLocation
          ? null
          : (publicCopyLocation ?? this.publicCopyLocation),
      publicFolderLocation: clearPublicFolderLocation
          ? null
          : (publicFolderLocation ?? this.publicFolderLocation),
    );
  }

  Map<String, Object?> toJson() => <String, Object?>{
        'id': id,
        'title': title,
        'createdAt': createdAt.toIso8601String(),
        'updatedAt': updatedAt.toIso8601String(),
        'sessions': sessions.map((session) => session.toJson()).toList(),
        'isStandalone': isStandalone,
        'category': category,
        'isFavorite': isFavorite,
        'isTrashed': isTrashed,
        'trashedAt': trashedAt?.toIso8601String(),
        'isDraft': isDraft,
        'notes': notes,
        'tags': tags,
        'bookmarks': bookmarks.map((bookmark) => bookmark.toJson()).toList(),
        'isAudioProtected': isAudioProtected,
        'audioProtectionSalt': audioProtectionSalt,
        'requiresAppPin': requiresAppPin,
        'aiGeneratedContent': aiGeneratedContent,
        'masterAudioPath': masterAudioPath,
        'publicCopyLocation': publicCopyLocation,
        'publicFolderLocation': publicFolderLocation,
      };

  factory RavenProject.fromJson(Map<String, Object?> json) {
    final rawSessions = json['sessions'];
    final createdAt = DateTime.parse(json['createdAt'] as String);
    final updatedAt =
        DateTime.tryParse(json['updatedAt'] as String? ?? '') ?? createdAt;
    final isTrashed = json['isTrashed'] as bool? ?? false;
    return RavenProject(
      id: json['id'] as String,
      title: json['title'] as String? ?? 'Untitled recording',
      createdAt: createdAt,
      updatedAt: updatedAt,
      sessions: rawSessions is List
          ? rawSessions
              .whereType<Map>()
              .map((item) => RavenAudioSession.fromJson(
                    Map<String, Object?>.from(item),
                  ))
              .toList()
          : <RavenAudioSession>[],
      isStandalone: json['isStandalone'] as bool? ?? false,
      category: json['category'] as String? ?? 'Uncategorized',
      isFavorite: json['isFavorite'] as bool? ?? false,
      isTrashed: isTrashed,
      trashedAt: DateTime.tryParse(json['trashedAt'] as String? ?? '') ??
          (isTrashed ? updatedAt : null),
      isDraft: json['isDraft'] as bool? ?? false,
      notes: json['notes'] as String? ?? '',
      tags: (json['tags'] as List?)?.whereType<String>().toList() ?? <String>[],
      bookmarks: (json['bookmarks'] as List?)
              ?.whereType<Map>()
              .map((item) =>
                  RavenBookmark.fromJson(Map<String, Object?>.from(item)))
              .toList() ??
          <RavenBookmark>[],
      isAudioProtected: json['isAudioProtected'] as bool? ?? false,
      audioProtectionSalt: json['audioProtectionSalt'] as String?,
      requiresAppPin: json['requiresAppPin'] as bool? ?? false,
      aiGeneratedContent: (json['aiGeneratedContent'] is Map)
          ? (json['aiGeneratedContent'] as Map)
              .map((key, value) => MapEntry(key.toString(), value.toString()))
          : <String, String>{},
      masterAudioPath: json['masterAudioPath'] as String?,
      publicCopyLocation: json['publicCopyLocation'] as String?,
      publicFolderLocation: json['publicFolderLocation'] as String?,
    );
  }
}
